import gurobipy as gp
from gurobipy import GRB

# Data
I = ['S1', 'S2', 'S3', 'S4']
J = ['C1', 'C2', 'C3', 'C4']
c = {
    ('S1', 'C1'): 883.91, ('S1', 'C2'): 0.04, ('S1', 'C3'): 0.03, ('S1', 'C4'): 44.45,
    ('S2', 'C1'): 543.75, ('S2', 'C2'): 23.68, ('S2', 'C3'): 23.67, ('S2', 'C4'): 447.75,
    ('S3', 'C1'): 537.34, ('S3', 'C2'): 23.76, ('S3', 'C3'): 498.95, ('S3', 'C4'): 440.60,
    ('S4', 'C1'): 1791.49, ('S4', 'C2'): 68.21, ('S4', 'C3'): 1432.48, ('S4', 'C4'): 1527.76
}
s = {'S1': 2531, 'S2': 20, 'S3': 210, 'S4': 241}
d = {'C1': 94, 'C2': 39, 'C3': 65, 'C4': 435}

# Model
m = gp.Model('transport')

# Decision variables
x = {}
for i in I:
    for j in J:
        x[i, j] = m.addVar(vtype=GRB.CONTINUOUS, name=f'x_{i}_{j}')

m.update()

# Objective
obj = gp.quicksum(c[i, j] * x[i, j] for i in I for j in J)
m.setObjective(obj, GRB.MINIMIZE)

# Supply constraints
for i in I:
    m.addConstr(gp.quicksum(x[i, j] for j in J) <= s[i], name=f'supply_{i}')

# Demand constraints
for j in J:
    m.addConstr(gp.quicksum(x[i, j] for i in I) == d[j], name=f'demand_{j}')

# Solve
m.optimize()

# Results
for i in I:
    for j in J:
        if x[i, j].X > 1e-6:
            print(f'{x[i, j].VarName} = {x[i, j].X}')
print(f'Objective: {m.objVal}')

import gurobipy as gp
from gurobipy import GRB

# Sets
I = ['I1','I2','I3','I4']  # warehouses
J = ['J1','J2','J3','J4']  # stores

# Parameters
c = {
    ('I1','J1'): 883.91, ('I1','J2'): 0.04, ('I1','J3'): 0.03, ('I1','J4'): 44.45,
    ('I2','J1'): 543.75, ('I2','J2'): 23.68, ('I2','J3'): 23.67, ('I2','J4'): 447.75,
    ('I3','J1'): 537.34, ('I3','J2'): 23.76, ('I3','J3'): 498.95, ('I3','J4'): 440.60,
    ('I4','J1'): 1791.49, ('I4','J2'): 68.21, ('I4','J3'): 1432.48, ('I4','J4'): 1527.76
}
d = {'J1':94, 'J2':39, 'J3':65, 'J4':435}
s = {'I1':2531, 'I2':20, 'I3':210, 'I4':241}

# Create model
m = gp.Model('transportation')

# Decision variables
x = {}
for i in I:
    for j in J:
        x[i,j] = m.addVar(vtype=GRB.CONTINUOUS, name=f'x_{i}_{j}')

# Objective
m.setObjective(gp.quicksum(c[i,j]*x[i,j] for i in I for j in J), GRB.MINIMIZE)

# Demand constraints
for j in J:
    m.addConstr(gp.quicksum(x[i,j] for i in I) == d[j], name=f'demand_{j}')

# Capacity constraints
for i in I:
    m.addConstr(gp.quicksum(x[i,j] for j in J) <= s[i], name=f'capacity_{i}')

# Optimize
m.optimize()

# Print solution
if m.status == GRB.OPTIMAL:
    for i in I:
        for j in J:
            val = x[i,j].X
            if val > 1e-6:
                print(f'{x[i,j].VarName} = {val}')

